// Picks the next Future Shift topic. Runs at 1 pm and 7 pm Dubai -> 35 videos over 17.5 days, then stops by itself.
// Video number = 2 per day counted from START_DATE (1 pm = first of the day, 7 pm = second).
// To restart the series later or start on another day: change START_DATE to the first day you want (Dubai date).
const START_DATE = '2026-10-05';
const TOTAL = 35;
const TOPICS = [["Artificial Intelligence", "neural", "Artificial_intelligence"], ["Blockchain", "chain", "Blockchain"], ["Industrial Robots", "robot", "Industrial_robot"], ["Smart Cities", "network", "Smart_city"], ["Quantum Computing", "orbit", "Quantum_computing"], ["Generative AI", "neural", "Generative_artificial_intelligence"], ["Smart Contracts", "chain", "Smart_contract"], ["Humanoid Robots", "robot", "Humanoid_robot"], ["Internet of Things", "network", "Internet_of_things"], ["Large Language Models", "neural", "Large_language_model"], ["Cryptocurrency", "chain", "Cryptocurrency"], ["Automation", "robot", "Automation"], ["Self-Driving Cars", "network", "Self-driving_car"], ["Fourth Industrial Revolution", "network", "Fourth_Industrial_Revolution"], ["Machine Learning", "neural", "Machine_learning"], ["Central Bank Digital Currency", "chain", "Central_bank_digital_currency"], ["3D Printing", "robot", "3D_printing"], ["Digital Twins", "network", "Digital_twin"], ["Computer Vision", "neural", "Computer_vision"], ["Decentralized Finance", "chain", "Decentralized_finance"], ["Delivery Robots", "robot", "Delivery_robot"], ["Drones", "network", "Unmanned_aerial_vehicle"], ["Brain-Computer Interfaces", "neural", "Brain–computer_interface"], ["Smart Grid", "network", "Smart_grid"], ["Augmented Reality", "orbit", "Augmented_reality"], ["Cloud Computing", "network", "Cloud_computing"], ["5G Networks", "network", "5G"], ["Nanotechnology", "orbit", "Nanotechnology"], ["Gene Editing", "orbit", "CRISPR_gene_editing"], ["Electric Vehicles", "network", "Electric_vehicle"], ["Edge Computing", "network", "Edge_computing"], ["Hydrogen Economy", "orbit", "Hydrogen_economy"], ["Virtual Reality", "orbit", "Virtual_reality"], ["Vertical Farming", "network", "Vertical_farming"], ["Cultured Meat", "orbit", "Cultured_meat"]];

const inputs = $input.all().map(i => i.json);
const fromSchedule = inputs.some(j => j && ('timestamp' in j || 'Readable date' in j));

const DAY = 86400000;
const dubai = new Date(Date.now() + 4 * 3600000);              // Dubai = UTC+4, no daylight saving
const start = Date.parse(START_DATE + 'T00:00:00Z');
const dayNo = Math.floor((dubai.getTime() - start) / DAY);
const slot = dayNo * 2 + (dubai.getUTCHours() >= 16 ? 1 : 0); // 13:00 run -> even, 19:00 run -> odd

let index = slot;
if (fromSchedule) {
  if (slot < 0) return [];          // series hasn't started yet
  if (slot >= TOTAL) return [];     // all 35 done -> stop quietly (nothing posted)
} else {
  index = Math.min(TOTAL - 1, Math.max(0, slot));   // manual Test run: preview the topic due now
}

const [topic, visual, wiki_title] = TOPICS[index];
return [{ json: {
  topic, visual, wiki_title,
  video_number: index + 1,
  of_total: TOTAL,
  music: 'music/future-' + ((index % 4) + 1) + '.mp3',
  _test: !fromSchedule,
} }];

// Builds the OpenRouter request for one Future Shift short.
const row = $('Pick Topic').first().json;
const pages = Object.values(($json.query && $json.query.pages) || {});
const page = pages[0] || {};
const source = page.extract || '';
if (source.length < 300) throw new Error('Wikipedia text missing or too short for: ' + row.wiki_title);

const SYSTEM = `You write 30-40 second vertical "Future Shift" shorts for T&I NEWS.
Each short explains ONE emerging technology and how it is moving societies from the industrial age to a future, technology-driven society.
Audience: curious non-engineers and business people worldwide (including the UAE and GCC). Tone: inspiring, clear, confident, honest.

RULES
1. Every fact (number, year, name, claim) must come from the SOURCE TEXT. Never invent statistics. If the source has no good number, use a year from the source in the "stat" scene with "isYear": true.
2. Narration is plain spoken English: short sentences, no jargon. If a technical word is needed, explain it in everyday words. Total narration across all scenes: 80-100 words.
3. The first scene must hook in under 3 seconds (a bold contrast, a surprising number, or a question).
4. Use 6-7 scenes from the SCENE MENU. Always start with "hook" and end with "outro". Include exactly one "shift" and exactly one "tech".
5. Present future effects as possibilities ("could", "is starting to") unless the source says they already happened.
6. Output ONLY valid JSON matching the OUTPUT SHAPE. No markdown, no commentary. Replace every "..." and 0 with real content.

SCENE MENU - every scene MUST have "type", "durationSec" (4-8) and "narration" (exact words spoken in that scene), plus:
- hook: kicker (<=4 words), headline (<=7 words, stops just before the payoff), highlight (1-2 words, the payoff, may end with a full stop)
- shift: then (<=32 chars, how the industrial age did it), next (<=32 chars, how the future society does it), optional thenLabel / nextLabel (<=18 chars)
- stat: value (a number from the SOURCE), prefix (optional, e.g. "$"), suffix (optional, <=10 chars, e.g. "billion" or "%"), isYear (true if value is a year), decimals (0 or 1), label (<=50 chars), sub (<=36 chars)
- tech: visual (neural|chain|robot|network|orbit - use the VISUAL HINT unless clearly wrong), title (<=26 chars, e.g. "How it works"), caption (<=44 chars)
- steps: title (<=26 chars), steps (exactly 4 items, each <=26 chars, how the technology works in plain words)
- impact: title (<=22 chars), items (exactly 3: {icon, sector (<=16 chars), change (<=30 chars)}); icon is one of factory|health|finance|retail|logistics|education|home|farm|city|energy|car|chip|shield|globe|people|chart
- outro: topic (the technology name, <=24 chars), line (<=36 chars, forward-looking), cta ("Follow for more future shifts")

OUTPUT SHAPE
{
  "scenes": [
    {"type": "hook", "durationSec": 5, "narration": "...", "kicker": "...", "headline": "...", "highlight": "..."},
    {"type": "shift", "durationSec": 6, "narration": "...", "then": "...", "next": "..."},
    {"type": "stat", "durationSec": 5, "narration": "...", "value": 0, "prefix": "", "suffix": "", "isYear": false, "decimals": 0, "label": "...", "sub": "..."},
    {"type": "tech", "durationSec": 6, "narration": "...", "visual": "neural", "title": "...", "caption": "..."},
    {"type": "steps", "durationSec": 7, "narration": "...", "title": "...", "steps": ["...", "...", "...", "..."]},
    {"type": "impact", "durationSec": 6, "narration": "...", "title": "...", "items": [{"icon": "health", "sector": "...", "change": "..."}, {"icon": "finance", "sector": "...", "change": "..."}, {"icon": "city", "sector": "...", "change": "..."}]},
    {"type": "outro", "durationSec": 4.5, "narration": "...", "topic": "...", "line": "...", "cta": "Follow for more future shifts"}
  ],
  "post": {
    "content": "<IG/FB/TikTok caption: plain-language hook + 1 line on how it changes society + 8-12 hashtags>",
    "youtube_title": "<max 90 chars, curiosity hook + technology name, ends with #Shorts>",
    "youtube_description": "<2-3 plain sentences + 3-5 hashtags>",
    "youtube_tags": ["<5-10 short tags>"],
    "linkedin_caption": "<professional tone, 3-5 short lines: what the technology does, what it changes for business and society, a question to the reader, max 3 hashtags>",
    "x_caption": "<one punchy line, max 100 characters, NO emojis, NO hashtags, NO website>"
  }
}`;

const user = [
  'TECHNOLOGY: ' + row.topic,
  'VISUAL HINT: ' + row.visual,
  'WIKIPEDIA ARTICLE: ' + (page.title || row.wiki_title),
  '',
  'SOURCE TEXT (the ONLY facts you may use):',
  source.slice(0, 14000),
].join('\n');

return [{ json: { brain_body: {
  model: 'openai/gpt-4o',
  temperature: 0.7,
  response_format: { type: 'json_object' },
  messages: [ { role: 'system', content: SYSTEM }, { role: 'user', content: user } ],
} } }];

// Parses + validates the Brain output and builds the GitHub dispatch body for render-future.yml.
let raw = $json.choices?.[0]?.message?.content || '';
raw = raw.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
let p;
try { p = JSON.parse(raw); } catch (e) { throw new Error('Brain did not return valid JSON: ' + raw.slice(0, 300)); }

const row = $('Pick Topic').first().json;
const TYPES = ['hook', 'shift', 'stat', 'tech', 'steps', 'impact', 'outro'];
const VISUALS = ['neural', 'chain', 'robot', 'network', 'orbit'];
const ICONS = ['factory','health','finance','retail','logistics','education','home','farm','city','energy','car','chip','shield','globe','people','chart'];
const str = (v, max) => String(v ?? '').trim().slice(0, max);

let scenes = (Array.isArray(p.scenes) ? p.scenes : [])
  .filter(s => s && typeof s === 'object')
  .map(s => ({ ...s, type: String(s.type || '').toLowerCase() }))
  .filter(s => TYPES.includes(s.type) && String(s.narration || '').trim());

for (const s of scenes) {
  s.narration = String(s.narration).trim();
  s.durationSec = Math.min(9, Math.max(4, Number(s.durationSec) || 5));
  if (s.type === 'hook') { s.kicker = str(s.kicker || 'The future', 30); s.headline = str(s.headline, 60); s.highlight = str(s.highlight, 24); }
  if (s.type === 'shift') { s.then = str(s.then, 40); s.next = str(s.next, 40); if (s.thenLabel) s.thenLabel = str(s.thenLabel, 20); if (s.nextLabel) s.nextLabel = str(s.nextLabel, 20); }
  if (s.type === 'stat') {
    s.value = Number(String(s.value).replace(/[^0-9.\-]/g, ''));
    s.isYear = !!s.isYear || (Number.isInteger(s.value) && s.value >= 1000 && s.value <= 2100 && !s.prefix && !s.suffix);
    s.decimals = s.isYear ? 0 : Math.min(1, Math.max(0, Number(s.decimals) || 0));
    s.prefix = str(s.prefix, 3); s.suffix = str(s.suffix, 12); s.label = str(s.label, 60); s.sub = str(s.sub, 40);
  }
  if (s.type === 'tech') { if (!VISUALS.includes(s.visual)) s.visual = row.visual || 'neural'; s.title = str(s.title || 'How it works', 30); s.caption = str(s.caption, 50); }
  if (s.type === 'steps') { s.title = str(s.title || 'How it works', 30); s.steps = (s.steps || []).slice(0, 4).map(x => str(x, 30)); }
  if (s.type === 'impact') {
    s.title = str(s.title || 'What changes', 26);
    s.items = (s.items || []).slice(0, 3).map(it => ({ icon: ICONS.includes(it.icon) ? it.icon : 'chart', sector: str(it.sector, 18), change: str(it.change, 34) }));
  }
  if (s.type === 'outro') { s.topic = str(s.topic || row.topic, 28); s.line = str(s.line || 'The future is being built now.', 40); s.cta = 'Follow for more future shifts'; }
}
// Drop scenes that would render broken.
scenes = scenes.filter(s =>
  !(s.type === 'stat' && !isFinite(s.value)) &&
  !(s.type === 'steps' && s.steps.length < 3) &&
  !(s.type === 'impact' && s.items.length < 2) &&
  !(s.type === 'hook' && (!s.headline || !s.highlight)));

// Exactly one hook first, one outro last.
let hook = scenes.find(s => s.type === 'hook');
let outro = scenes.find(s => s.type === 'outro');
scenes = scenes.filter(s => s.type !== 'hook' && s.type !== 'outro');
if (!hook) throw new Error('Brain returned no usable hook scene. Types: ' + JSON.stringify((p.scenes || []).map(s => s && s.type)));
if (!outro) outro = { type: 'outro', durationSec: 4.5, topic: row.topic, line: 'The future is being built now.', cta: 'Follow for more future shifts', narration: row.topic + '. Follow T&I News for more future shifts.' };
scenes = [hook, ...scenes.slice(0, 5), outro];
if (scenes.length < 5) throw new Error('Brain returned too few usable scenes: ' + scenes.map(s => s.type).join(','));

// Fixed brand, music and posting targets (never trusted to the model).
const out = {
  brand: { name: 'T&I NEWS', url: 'tai.news', series: 'FUTURE SHIFT', bg: '#F7F2E6', bg2: '#EADFC6', accent: '#B07F22', accentSoft: '#D8B565', text: '#0B1F44' },
  sfx: true,
  musicFile: row.music || 'music/future-1.mp3',
  musicVolume: 0.4,
  scenes,
};

function withSite(text) {
  const cta = '🔗 Visit tai.news for more';
  let t = String(text || '').trim();
  if (!t || /tai\.news/i.test(t)) return t;
  const lines = t.split('\n');
  const tagLine = lines.findIndex(l => /^\s*#/.test(l));
  if (tagLine === -1) return t + '\n\n' + cta;
  return lines.slice(0, tagLine).join('\n').trim() + '\n\n' + cta + '\n\n' + lines.slice(tagLine).join('\n').trim();
}
function xCaption(text) {
  const site = ' tai.news';
  let t = String(text || '')
    .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, '')
    .replace(/#\S+/g, '')
    .replace(/https?:\/\/\S+|\btai\.news\b/gi, '')
    .replace(/\s+/g, ' ').trim();
  const max = 119 - site.length;
  if (t.length > max) t = t.slice(0, max).replace(/\s+\S*$/, '').replace(/[,;:\s]+$/, '') + '…';
  return t + site;
}

const b = p.post || {};
if (!b.content) throw new Error('Brain returned no post.content caption');
let ytTitle = (b.youtube_title || (row.topic + ': ' + hook.headline + ' ' + hook.highlight + ' #Shorts')).trim();
if (ytTitle.length > 100) ytTitle = ytTitle.slice(0, 97) + '...';
out.post = {
  content: withSite(b.content),
  // Facebook 7748, Instagram 7752, TikTok 7908, YouTube 7751, LinkedIn 9116. X 7747 is a separate post.
  account_ids: [7748, 7752, 7908, 7751, 9116],
  publish_now: true,
  platform_content: {
    youtube: {
      title: ytTitle,
      description: withSite(b.youtube_description || b.content),
      privacy: 'public',
      made_for_kids: false,
      is_short: true,
      tags: Array.isArray(b.youtube_tags) ? b.youtube_tags.slice(0, 15) : [],
    },
    linkedin: { content: withSite(b.linkedin_caption || b.content) },
  },
  x: { account_ids: [7747], content: xCaption(b.x_caption || hook.narration) },
};

return [{ json: {
  props: out,
  // Manual "Test run" renders only; the schedule posts.
  dispatch_body: { ref: 'main', inputs: { props: JSON.stringify(out), post: row._test ? 'false' : 'true', voice: 'am_michael' } },
} }];
